import {riskEvidenceHTML} from './risk-statistics.js';
import {loanDue} from './credit.js';
import {fortune,satisfaction} from './life-risk.js';
import {CONCEPTS,comparisonRows,learningPath,studyChoices,contemporaryBrief} from './learning.js';
import {avatarScene,lifeStage} from './avatar.js';
import {MARKET_EVENTS} from './market-data.js';
import {choices,income,salaryIncome,expenses,worth,age} from './engine.js';
import {reportFor} from './market.js';

export function renderStudyEvent(s,{escape:e,won,date}){
 const p=s.pending,brief=contemporaryBrief(s.month);
 if(!p)return `<article class="study-event"><span class="eyebrow">${s.ended?'MY LEARNING RECORD':'BETWEEN CHAPTERS'}</span><h3>${s.ended?'내가 지나온 경제사의 장면들':'사건 사이에도, 삶은 이어진다.'}</h3><p>${s.ended?'읽은 역사와 다시 살펴볼 개념을 수첩에서 확인해요. 수익률 순위로 학습을 평가하지 않습니다.':'이달의 가계와 자산을 확인하거나 다음 생일로 시간을 보내세요. 중간에 학습 사건이 있으면 먼저 멈춥니다.'}</p><button class="btn secondary small" data-tab="notebook">경제 개념 수첩 →</button></article>`;
 if(p.kind!=='history-study')return `<article class="study-event"><span class="eyebrow">${e(p.category)} / 나의 삶</span><h3>${e(p.title)}</h3><p>${e(p.text)}</p>${p.kind==='risk'?riskEvidenceHTML(s,e):''}<div class="study-options">${choices(s).slice(0,3).map(c=>`<button data-choice="${c.id}" class="study-option"><b>${e(c.title)}</b><small>${e(c.detail)}</small></button>`).join('')}${choices(s).length>3?`<details class="other-choices"><summary>다른 선택 ${choices(s).length-3}개</summary>${choices(s).slice(3).map(c=>`<button data-choice="${c.id}" class="study-option"><b>${e(c.title)}</b><small>${e(c.detail)}</small></button>`).join('')}</details>`:''}</div></article>`;
 if(p.stage==='before')return `<article class="study-event"><span class="eyebrow">01 / 결과를 보기 전</span><h3>${e(p.title)}</h3><p>${e(p.text)}</p>${brief?`<div class="study-fact"><b>${e(brief.title)}</b><p>${e(brief.text)}</p><a href="${e(brief.url)}" target="_blank" rel="noopener noreferrer">${date(brief.date)} · ${e(brief.source)} ↗</a></div>`:'<p class="note">이 시점의 별도 사전 정보 카드는 미수록입니다. 결과를 보지 않고 일반적인 판단 기준부터 선택합니다.</p>'}<p class="study-hint">${age(s)<19?'어린 시절에는 가족이 어떤 기준으로 결정하는지 관찰해요.':'준비 선택은 자동 매매하지 않습니다. 선택 후 이전 월 가격에서 직접 자산을 조정할 수 있어요.'}</p><div class="study-options">${studyChoices().map(c=>`<button data-choice="${c.id}" class="study-option"><b>${c.title}</b><small>${c.detail}</small></button>`).join('')}</div></article>`;
 const event=MARKET_EVENTS.find(x=>x.id===p.economicId),report=reportFor(s,p.economicId);
 const channel=event.policy?'정책 방향 → 산업의 기대·투자와 내수 → 가계·기업의 선택. 발표와 집행, 성과는 구분합니다.':event.id.includes('hike')||event.id.includes('cut')||event.id.includes('zero')?'금융정책 → 자금 조달 비용과 자산 평가 → 환율·기업·가계. 다른 나라의 정책금리는 한국 예금금리와 다릅니다.':'대외 사건 → 불확실성·금융 또는 생활 여건 → 한국의 산업·가계. 모든 자산이 같은 방향으로 움직이지는 않습니다.';
 return `<article class="study-event"><span class="eyebrow">02 / 사건 경험 · 03 / 해설</span><h3>${e(event.title)}</h3><p class="event-outcome">${date(event.date)} · 내 자산의 사건 효과 <b>${won(report?.delta||0)}</b><br>사실의 날짜와 게임의 가정 손익을 구분합니다.</p><details class="event-explanation"><summary>왜 이런 일이 생겼을까? · 실제 기록과 해설</summary><div class="study-fact"><b>실제 역사 기록</b><p>${date(event.date)} · ${e(event.title)}</p><a href="${e(event.url)}" target="_blank" rel="noopener noreferrer">${e(event.source)} · 사실 확인 ↗</a>${event.policyUrl?`<a href="${e(event.policyUrl)}" target="_blank" rel="noopener noreferrer">정책 발표 근거 ↗</a>`:''}</div><p class="study-hint">나의 준비 기준 · ${e(s.learning.before?.month===s.month?(studyChoices().find(c=>c.id===s.learning.before.choice)?.title||'준비 기록 없음'):'시작 월 이후 처음 만난 사건')}</p><div class="study-explain"><b>경제를 이해하는 경로</b><p>${channel}</p></div><div class="study-model"><b>이번 게임에서 일어난 일</b><p>${e(event.text)}</p><strong>내 보유 자산의 사건 효과 ${won(report?.delta||0)}</strong><p class="note">이 금액은 가정한 가격 충격만 계산한 값입니다. 실제 역사 수익률이나 사건의 인과 추정치가 아니며 월 수입·지출과는 별도입니다.${event.policy?' 정책 발표 자체의 즉시 가격 보상은 없고, 다음 달부터 정책 모형이 작용합니다.':''}</p></div><details class="study-reflection"><summary>생각해 보기</summary><p>같은 사건에서 현금과 달러의 역할은 어떻게 달랐을까요?<br>자산 수익이 좋아도 생활비를 감당할 여유가 없다면 어떤 선택이 필요할까요?<br>실제 사실과 게임이 가정한 효과를 각각 한 가지씩 찾아보세요.</p></details></details><div class="study-options"><button class="study-option" data-choice="understood"><b>해설을 읽고 다음 장면으로</b><small>관련 개념을 수첩에 기록 · 금전 보상 없음</small></button><button class="study-option" data-choice="review"><b>개념 수첩에서 다시 살펴보기</b><small>복습 표시를 남기고 개념 수첩 열기</small></button></div></article>`;
}
export function renderLearning(s,ctx){const {escape:e,won,date}=ctx,a=lifeStage(s),minor=s.startMode==='birth'&&a.years<19,net=income(s)-expenses(s)-loanDue(s),f=fortune(s);
 return `<div class="compact-stage"><aside class="compact-wallet"><span class="mini-label">${minor?'가족의 가계':'나의 자산'}</span><dl><div><dt>순자산</dt><dd>${won(worth(s))}</dd></div><div><dt>사용 가능한 현금</dt><dd>${won(s.cash)}</dd></div><div><dt>총부채</dt><dd>${won(s.debt)}</dd></div></dl><details class="compact-budget"><summary>예상 월 잔액 ${won(net)}</summary><p>수입 ${won(income(s))}<br>생활·주거비 ${won(expenses(s))}<br>대출 예정 원리금 ${won(loanDue(s))}<br>실제 현금 납부와 미납은 월 장부에 따로 기록합니다.</p></details><div class="compact-salary"><span>${minor?'가족 월 급여 · 모형':'월 급여 · 모형'}</span><b>${won(salaryIncome(s))}</b></div><div class="wallet-actions"><button data-quick-trade="buy" ${minor||s.ended||!s.market?'disabled':''}>매수</button><button data-quick-trade="sell" ${minor||s.ended||!s.market?'disabled':''}>매도</button><button data-reserve-open="deposit" ${minor||s.ended?'disabled':''}>예금잔액</button><button data-tab="finance">대출·상환</button></div><p class="note">${minor?'어린 시절에는 가족 가계를 관찰합니다. 직접 금융 선택은 19세부터 열립니다.':'금융 거래는 금액과 영향을 확인한 뒤 확정합니다.'}</p><button class="text-button" data-tab="economy">경제 지표 자세히 ↗</button></aside><section class="compact-person"><span class="mini-label">${e(s.name)}의 ${minor?'성장':'오늘'}</span><div class="life-status-pills"><span>삶 만족도 <b>${satisfaction(s)}</b></span><span>인생 총운 <b>${f.grade}</b></span></div>${avatarScene(s)}<details class="compact-status-help"><summary>상태의 의미</summary><p>만족은 선택에 따른 게임 지표입니다. 총운은 겪은 우연의 요약입니다. 운세·굿을 선택하면 별도의 운 체감이 올라갑니다. 어느 지표도 미래 사고 확률이나 투자 실력을 뜻하지 않습니다.</p></details><button class="text-button small" data-avatar-motion="toggle">움직임 재생·멈춤</button></section><section class="compact-choice"><div class="compact-event-scroll">${renderStudyEvent(s,ctx)}</div>${s.lastDecision?`<details class="locked-choice"><summary>✓ 확정한 선택 · ${e(s.lastDecision.title)}</summary><p>${date(s.lastDecision.month)} · ${e(s.lastDecision.event)}<br>${e(s.lastDecision.detail)}<br>이 선택은 변경할 수 없습니다.</p></details>`:''}<div class="compact-time-controls"><button class="btn" data-advance="1" ${s.pending||s.ended?'disabled':''}>다음 달 →</button><button class="btn secondary" data-advance="12" ${s.pending||s.ended?'disabled':''}>다음 사건까지</button></div><p class="note compact-time-note">선택 확정 후 직접 진행 · 최대 12개월 · 사건에서 멈춤</p></section></div>${s.ended?`<div class="compact-ended"><b>이 삶의 마지막 장에 도착했습니다.</b><button class="btn small" data-tab="records">결산과 영수증 보기 →</button></div>`:''}<details class="compact-more"><summary>선택 비교와 경제사 타임라인</summary>${s.learning?renderComparison(s,ctx):'<p>이전 기록에는 선택 비교를 소급 생성하지 않습니다.</p>'}${renderStudyTimeline(s,ctx)}</details><p class="compact-model-note">${s.month>'2026-10'?'가상 미래':'경제사 학습'} · ${s.rules?s.rules.difficulty==='hard'?'어려움':'보통':'이전 저장 · 생활 사건 확장 미적용'} · 금융·생활 사건은 모형 데이터입니다. 실제 과거 시세와 은행 상품 조건은 미연결입니다.</p>`;
}

export function renderComparison(s,{won,date}){const rows=comparisonRows(s),c=s.learning.comparison;return `<section class="study-comparison"><div class="section-heading"><div><span class="eyebrow">SAME START, DIFFERENT ASSETS</span><h3>같은 돈을 다르게 두었다면?</h3></div><span>${date(c.start)} → ${date(s.month)}</span></div><p>시작 자금 ${won(c.budget)}을 한 자산에만 두고 유지한 별도 실험입니다. 실제 내 가계와 연결된 자금이 아닙니다.</p><div class="study-table-scroll"><table><thead><tr><th>선택</th><th>현재 모형 평가액</th><th>시작 물가 기준</th><th>함께 생각할 위험</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${r.name}</th><td>${won(r.value)}<small>${won(r.change)}</small></td><td>${won(r.real)}</td><td>${r.risk}</td></tr>`).join('')}</tbody></table></div><p class="note">예금은 월 이자를 재투자하는 가정입니다. 생활비·급여·세금·주거·배당은 비교에서 제외합니다. 실제 플레이 예금의 이자는 현금으로 지급됩니다. 주식·달러는 현재 전량 매도 수수료까지 반영하며 소수 수량과 원 단위 반올림에서 실제 게임 거래와 작은 차이가 있을 수 있습니다. 미래 가격과 투자 정답을 제시하지 않습니다.</p></section>`;}
export function renderStudyTimeline(s,{escape:e,date}){const past=MARKET_EVENTS.filter(x=>x.month<=s.month),completed=s.learning?.entries||[];return `<section class="study-timeline"><div class="section-heading"><h3>내가 지나온 경제사</h3><span>현재까지의 내장 사건 ${past.length}개</span></div><div class="study-timeline-track">${past.map(x=>`<article><time>${date(x.date)}</time><b>${e(x.title)}</b><span>${completed.some(c=>c.id===x.id)?'내 학습 기록':x.month<s.start?'시작 이전 역사':'현재까지의 역사'}</span></article>`).join('')||'<p>첫 사건을 만나면 타임라인에 기록됩니다.</p>'}</div><p class="note">아직 오지 않은 사건의 이름과 결과는 표시하지 않습니다. 실제 역사 기록은 2026년 10월까지만 다룹니다.</p></section>`;}
export function renderNotebook(s,{escape:e,won,date}){const unlocked=s.learning?.concepts||[],path=learningPath(s);return `<section class="notebook-heading"><span class="eyebrow">MY ECONOMICS NOTEBOOK</span><h2>겪어 봤으니,<br>조금 더 이해할 수 있도록.</h2><p>공개된 개념 ${unlocked.length}/${CONCEPTS.length} · 읽고 기록한 역사 장면 ${path.length}개</p></section><div class="notebook-grid">${CONCEPTS.map(c=>`<article class="card ${unlocked.includes(c.id)?'unlocked':'locked'}"><span class="mini-label">${unlocked.includes(c.id)?'경험한 개념':'미리 읽어볼 개념'}</span><h3>${c.name}</h3><p>${c.text}</p>${c.url?`<a href="${c.url}" target="_blank" rel="noopener noreferrer">한국은행 설명 읽기 ↗</a>`:'<small>게임 학습 설명 · 실제 결과의 보장 없음</small>'}${path.filter(p=>p.concepts.includes(c.id)).map(p=>`<div class="notebook-example"><time>${date(p.month)}</time><b>${e(p.event.title)}</b><span>${p.reflection==='review'?'복습 표시':'읽고 기록함'}</span></div>`).join('')}</article>`).join('')}</div>${s.learning?renderLearningSummary(s,{escape:e,won,date}):''}`;}
function renderLearningSummary(s,{escape:e}){const entries=learningPath(s),review=entries.filter(x=>x.reflection==='review');return `<section class="study-summary"><span class="eyebrow">UNDERSTANDING, NOT A WEALTH RANK</span><h3>나의 학습 발자국</h3><div><strong>${entries.length}<small>읽고 기록한 역사 장면</small></strong><strong>${s.learning.concepts.length}<small>경험한 경제 개념</small></strong><strong>${review.length}<small>다시 살펴볼 장면</small></strong></div><p>이 숫자는 이해도를 검증한 시험 점수가 아닙니다. 판단 근거와 결과를 되돌아보는 기록입니다.</p>${review.map(x=>`<p>복습 · ${e(x.event.title)}</p>`).join('')}<button class="btn secondary small" data-ui="export">학습과 삶의 기록 내려받기</button></section>`;}
